examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchSegmentedControl(
        options = listOf({{layouts.0.label}}, {{layouts.1.label}}),
        selectedIndex = if (layout == MonarchFileListLayout.{{layouts.0.value|pascal}}) 0 else 1,
        onSelect = {
            layout = if (it == 0) MonarchFileListLayout.{{layouts.0.value|pascal}} else MonarchFileListLayout.{{layouts.1.value|pascal}}
        },
    )
    MonarchFileList(
        items = listOf(
            MonarchFileListItem(id = {{files.0.id}}, name = {{files.0.name}}, sizeBytes = {{files.0.size}}, meta = {{files.0.meta}}),
            MonarchFileListItem(id = {{files.1.id}}, name = {{files.1.name}}, sizeBytes = {{files.1.size}}, meta = {{files.1.meta}}),
            MonarchFileListItem(id = {{files.2.id}}, name = {{files.2.name}}, sizeBytes = {{files.2.size}}, meta = {{files.2.meta}}),
            MonarchFileListItem(id = {{files.3.id}}, name = {{files.3.name}}, sizeBytes = {{files.3.size}}, meta = {{files.3.meta}}),
            MonarchFileListItem(id = {{files.4.id}}, name = {{files.4.name}}, sizeBytes = {{files.4.size}}, meta = {{files.4.meta}}),
        ),
        modifier = Modifier.height(520.dp),
        layout = layout,
        selected = selected,
        onSelectedChange = { selected = it },
        onOpen = {},
        label = {{label}},
        bulkActions = listOf(
            MonarchBulkAction(id = "download", title = {{bulkActions.0}}) {},
            MonarchBulkAction(id = "trash", title = {{bulkActions.1}}, destructive = true) {},
        ),
        actions = { item ->
            Box {
                MonarchIconButton(label = "More actions for " + item.name, onClick = { menuFor = item.id }) {
                    MonarchIcon(SampleIcons.More, contentDescription = null)
                }
                MonarchMenu(expanded = menuFor == item.id, onDismissRequest = { menuFor = null }) {
                    MonarchMenuItem(text = {{menu.0}}, onClick = { menuFor = null })
                    MonarchMenuItem(text = {{menu.1}}, onClick = { menuFor = null })
                    MonarchMenuItem(text = {{menu.2}}, onClick = { menuFor = null }, destructive = true)
                }
            }
        },
    )
}

examples.setupTemplate:
var layout by remember { mutableStateOf(MonarchFileListLayout.{{layout|pascal}}) }
var selected by remember { mutableStateOf(setOf<String>()) }
var menuFor by remember { mutableStateOf<String?>(null) }

examples.setup:
var layout by remember { mutableStateOf(MonarchFileListLayout.List) }
var selected by remember { mutableStateOf(setOf<String>()) }
var menuFor by remember { mutableStateOf<String?>(null) }

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchSegmentedControl(
        options = listOf("List", "Grid"),
        selectedIndex = if (layout == MonarchFileListLayout.List) 0 else 1,
        onSelect = {
            layout = if (it == 0) MonarchFileListLayout.List else MonarchFileListLayout.Grid
        },
    )
    MonarchFileList(
        items = listOf(
            MonarchFileListItem(id = "1", name = "project-brief.pdf", sizeBytes = 1_800_000, meta = "Edited yesterday"),
            MonarchFileListItem(id = "2", name = "wireframes.png", sizeBytes = 4_200_000, meta = "Edited 3 days ago"),
            MonarchFileListItem(id = "3", name = "estimates.xlsx", sizeBytes = 96_000, meta = "Edited last week"),
            MonarchFileListItem(id = "4", name = "kickoff-recording.mp4", sizeBytes = 182_000_000, meta = "Edited last week"),
            MonarchFileListItem(id = "5", name = "source-assets.zip", sizeBytes = 54_000_000, meta = "Edited last month"),
        ),
        modifier = Modifier.height(520.dp),
        layout = layout,
        selected = selected,
        onSelectedChange = { selected = it },
        onOpen = {},
        label = "Project files",
        bulkActions = listOf(
            MonarchBulkAction(id = "download", title = "Download") {},
            MonarchBulkAction(id = "trash", title = "Move to trash", destructive = true) {},
        ),
        actions = { item ->
            Box {
                MonarchIconButton(label = "More actions for " + item.name, onClick = { menuFor = item.id }) {
                    MonarchIcon(SampleIcons.More, contentDescription = null)
                }
                MonarchMenu(expanded = menuFor == item.id, onDismissRequest = { menuFor = null }) {
                    MonarchMenuItem(text = "Download", onClick = { menuFor = null })
                    MonarchMenuItem(text = "Rename", onClick = { menuFor = null })
                    MonarchMenuItem(text = "Move to trash", onClick = { menuFor = null }, destructive = true)
                }
            }
        },
    )
}
